contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address other) public payable {
        require(other != address(this));
        c.getTokens(); if (__ESBMC_reverted()) return;
        assert(c.blacklist(address(this)) == true && c.blacklist(other) == false);
    }

    receive() external payable {}
}

